type TargetService struct {
	rootKey    []byte
	sharedKey  []byte // Общий симметричный ключ между TargetService и 2FAService
}

// IssueToken выпускает токен с обязательным требованием 2FA от стороннего сервиса
func (s *TargetService) IssueToken(userID string) *DistributedMacaroon {
	h := hmac.New(sha256.New, s.rootKey)
	h.Write([]byte(userID))
	sig := h.Sum(nil)

	// Шифруем требование общим ключом с сервисом 2FA
	hTicket := hmac.New(sha256.New, s.sharedKey)
	hTicket.Write([]byte("require:2fa_verified"))
	ticket := hTicket.Sum(nil)

	m := &DistributedMacaroon{
		ID:        userID,
		Signature: sig,
		Caveats: []ThirdPartyCaveat{
			{Location: "https://auth.2fa.corp", Ticket: ticket},
		},
	}
	return m
}

// TwoFactorService эмулирует сторонний сервис двухфакторной аутентификации
type TwoFactorService struct {
	sharedKey []byte
}

// IssueDischarge проверяет 2FA код пользователя и выпускает подтверждающий токен (Discharge)
func (s *TwoFactorService) IssueDischarge(ticket []byte, smsCode string) ([]byte, error) {
	if smsCode != "777-123" {
		return nil, fmt.Errorf("invalid 2fa code")
	}

	// Выпускаем криптографическое доказательство успешного 2FA
	h := hmac.New(sha256.New, s.sharedKey)
	h.Write(ticket)
	h.Write([]byte("status=discharged_ok"))
	return h.Sum(nil), nil
}

// VerifyAll производит локальную оффлайн проверку всей связки токенов
func (s *TargetService) VerifyAll(m *DistributedMacaroon, dischargeToken []byte) (bool, error) {
	if len(m.Caveats) > 0 && dischargeToken == nil {
		return false, fmt.Errorf("missing discharge token for third-party caveat")
	}

	// Проверяем Discharge Token от 2FA сервиса локально (без сети!)
	expectedDischargeH := hmac.New(sha256.New, s.sharedKey)
	expectedDischargeH.Write(m.Caveats[0].Ticket)
	expectedDischargeH.Write([]byte("status=discharged_ok"))
	expectedDischarge := expectedDischargeH.Sum(nil)

	if subtle.ConstantTimeCompare(dischargeToken, expectedDischarge) != 1 {
		return false, fmt.Errorf("discharge token verification failed (2fa proof invalid)")
	}

	return true, nil
}

func main() {
	sharedSecret := []byte("SharedSecretBetweenTargetAnd2FA2026")
	targetSvc := &TargetService{rootKey: []byte("TargetRootKey"), sharedKey: sharedSecret}
	twoFASvc := &TwoFactorService{sharedKey: sharedSecret}

	// 1. Сервер ресурсов выдает токен с требованием 2FA
	macaroon := targetSvc.IssueToken("user_alice")
	fmt.Println("=== 1. Выдан Macaroon с Third-Party Caveat ===")
	fmt.Printf("Требуется подтверждение от: %s\n\n", macaroon.Caveats[0].Location)

	// 2. Попытка обратиться к ресурсу БЕЗ discharge токена
	fmt.Println("=== 2. Попытка доступа без подтверждения 2FA ===")
	_, errWithout2FA := targetSvc.VerifyAll(macaroon, nil)
	fmt.Printf("Результат: ❌ %v\n\n", errWithout2FA)

	// 3. Клиент идет в 2FA сервис, вводит СМС и получает Discharge Macaroon
	fmt.Println("=== 3. Клиент проходит 2FA и получает Discharge Macaroon ===")
	discharge, err := twoFASvc.IssueDischarge(macaroon.Caveats[0].Ticket, "777-123")
	if err != nil {
		panic(err)
	}
	fmt.Printf("Discharge токен получен: %x...\n\n", discharge[:8])

	// 4. Клиент предъявляет оба токена целевому сервису
	fmt.Println("=== 4. Проверка связки токенов на целевом сервисе (Offline!) ===")
	ok, err := targetSvc.VerifyAll(macaroon, discharge)
	fmt.Printf("Результат проверки: ✅ Доступ разрешен=%t (ошибка: %v)\n", ok, err)
}

package main

import (
	"crypto/ed25519"
	"crypto/rand"
	"fmt"
	"strings"
	"time"
)

// DatalogFact представляет логический факт Biscuit (например: operation("read"))
type DatalogFact struct {
	Predicate string
	Argument  string
}

// DatalogCheck представляет проверяемое правило (например: check if operation == "read")
type DatalogCheck struct {
	RequiredPredicate string
	ExpectedValue     string
}

type BiscuitBlock struct {
	Facts  []DatalogFact
	Checks []DatalogCheck
}

type MockBiscuitToken struct {
	Blocks    []BiscuitBlock
	Signature []byte
}

func main() {
	_, privKey, _ := ed25519.GenerateKey(rand.Reader)
	_ = privKey

	// 1. Сервер выпускает корневой Biscuit токен
	rootBlock := BiscuitBlock{
		Facts: []DatalogFact{
			{Predicate: "user_id", Argument: "usr_1092"},
			{Predicate: "right", Argument: "documents:write"},
			{Predicate: "right", Argument: "documents:read"},
		},
		Checks: []DatalogCheck{
			// Корневое ограничение: срок жизни токена
			{RequiredPredicate: "env_time_valid", ExpectedValue: "true"},
		},
	}

	biscuit := &MockBiscuitToken{
		Blocks: []BiscuitBlock{rootBlock},
	}

	fmt.Println("=== 1. Выпущен корневой Biscuit токен ===")
	fmt.Println("Факты корневого блока:")
	for _, f := range rootBlock.Facts {
		fmt.Printf("  • %s(\"%s\")\n", f.Predicate, f.Argument)
	}

	// 2. Оффлайн-аттенюация: клиент сужает права токена до Read-Only!
	fmt.Println("\n=== 2. Оффлайн-аттенюация (Добавление блока ограничений Datalog) ===")
	attenuatedBlock := BiscuitBlock{
		Checks: []DatalogCheck{
			// Добавляем жесткое правило: разрешена ТОЛЬКО операция read!
			{RequiredPredicate: "request_operation", ExpectedValue: "read"},
		},
	}
	biscuit.Blocks = append(biscuit.Blocks, attenuatedBlock)
	fmt.Println("Клиент добавил новое правило: check if request_operation(\"read\")")

	// 3. Выполнение запроса: Запрос на запись (Write)
	fmt.Println("\n=== 3. Проверка запроса на запись (request_operation = write) ===")
	ambientFactsWrite := map[string]string{
		"env_time_valid":    "true",
		"request_operation": "write", // Попытка записи!
	}

	passWrite, errWrite := verifyBiscuit(biscuit, ambientFactsWrite)
	fmt.Printf("Результат проверки операции 'write':\n❌ Доступ=%t (Ошибка: %v)\n\n", passWrite, errWrite)

	// 4. Выполнение запроса: Запрос на чтение (Read)
	fmt.Println("=== 4. Проверка запроса на чтение (request_operation = read) ===")
	ambientFactsRead := map[string]string{
		"env_time_valid":    "true",
		"request_operation": "read", // Чтение
	}

	passRead, errRead := verifyBiscuit(biscuit, ambientFactsRead)
	fmt.Printf("Результат проверки операции 'read':\n✅ Доступ=%t (Ошибка: %v)\n", passRead, errRead)
}

func verifyBiscuit(b *MockBiscuitToken, ambientFacts map[string]string) (bool, error) {
	for i, block := range b.Blocks {
		for _, check := range block.Checks {
			val, exists := ambientFacts[check.RequiredPredicate]
			if !exists || val != check.ExpectedValue {
				return false, fmt.Errorf("блок #%d нарушил правило Datalog: check if %s == \"%s\" (фактическое: \"%s\")",
					i, check.RequiredPredicate, check.ExpectedValue, val)
			}
		}
	}
	return true, nil
}

package main

import (
	"encoding/base64"
	"fmt"

	"github.com/golang-jwt/jwt/v5"
)

// StrictVerifyJWT производит бескомпромиссную проверку токена
func StrictVerifyJWT(tokenStr string, secret []byte) bool {
	token, err := jwt.Parse(tokenStr, func(t *jwt.Token) (any, error) {
		// Строго типизированная проверка метода
		if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
			return nil, fmt.Errorf("disallowed algorithm: %v", t.Header["alg"])
		}
		return secret, nil
	},
		// Жесткий белый список методов
		jwt.WithValidMethods([]string{"HS256"}),
	)

	return err == nil && token.Valid
}

func craftNoneToken(algVariant string, withTrailingDot bool) string {
	headerJSON := fmt.Sprintf(`{"alg":"%s","typ":"JWT"}`, algVariant)
	payloadJSON := `{"sub":"evil_attacker","role":"admin"}`

	hB64 := base64.RawURLEncoding.EncodeToString([]byte(headerJSON))
	pB64 := base64.RawURLEncoding.EncodeToString([]byte(payloadJSON))

	if withTrailingDot {
		return hB64 + "." + pB64 + "."
	}
	return hB64 + "." + pB64
}

func main() {
	secret := []byte("StrictMasterSecretKey2026")

	// Тестовые векторы атак 'alg: none'
	testCases := []struct {
		name            string
		alg             string
		withTrailingDot bool
	}{
		{"Классический 'none' с точкой", "none", true},
		{"Классический 'none' без точки", "none", false},
		{"Верхний регистр 'NONE'", "NONE", true},
		{"Смешанный регистр 'nOnE'", "nOnE", true},
		{"Заголовок 'None'", "None", true},
	}

	fmt.Println("=== Регрессионное тестирование защиты от атаки 'alg: none' ===")
	allBlocked := true

	for i, tc := range testCases {
		badToken := craftNoneToken(tc.alg, tc.withTrailingDot)
		isValid := StrictVerifyJWT(badToken, secret)

		status := "🛡️ ЗАБЛОКИРОВАН (Успех)"
		if isValid {
			status = "🚨 ПРОПУЩЕН (Критическая уязвимость!)"
			allBlocked = false
		}

		fmt.Printf("[%d] %-30s -> %s\n", i+1, tc.name, status)
	}

	fmt.Println("\n--- Итог аудита безопасности ---")
	if allBlocked {
		fmt.Println("✅ Все векторы атаки 'alg: none' успешно отражены!")
	} else {
		fmt.Println("❌ Внимание! Обнаружена брешь в валидаторе токенов!")
	}
}

package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"sync"
	"time"
)

// UserSessionData представляет полезную нагрузку серверной сессии
type UserSessionData struct {
	UserID    string    `json:"user_id"`
	Email     string    `json:"email"`
	Role      string    `json:"role"`
	CreatedAt time.Time `json:"created_at"`
}

type SessionItem struct {
	Data      UserSessionData
	ExpiresAt time.Time
}

// MockRedisClient эмулирует быстрый in-memory Redis с TTL
type MockRedisClient struct {
	mu   sync.RWMutex
	data map[string]SessionItem
}

func NewMockRedisClient() *MockRedisClient {
	return &MockRedisClient{data: make(map[string]SessionItem)}
}

func (r *MockRedisClient) SetEX(key string, val UserSessionData, ttl time.Duration) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.data[key] = SessionItem{
		Data:      val,
		ExpiresAt: time.Now().Add(ttl),
	}
}

func (r *MockRedisClient) Get(key string) (*UserSessionData, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	item, ok := r.data[key]
	if !ok || time.Now().After(item.ExpiresAt) {
		return nil, false
	}
	return &item.Data, true
}

func (r *MockRedisClient) Del(key string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	delete(r.data, key)
}

// SessionService управляет сессиями пользователей
type SessionService struct {
	redis *MockRedisClient
}

func NewSessionService(redis *MockRedisClient) *SessionService {
	return &SessionService{redis: redis}
}

// Login создает 32-байтовый криптостойкий токен и сохраняет состояние в Redis
func (s *SessionService) Login(userID, email, role string, ttl time.Duration) (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	sessionToken := hex.EncodeToString(b) // 64 символа hex

	data := UserSessionData{
		UserID:    userID,
		Email:     email,
		Role:      role,
		CreatedAt: time.Now(),
	}

	s.redis.SetEX("session:"+sessionToken, data, ttl)
	return sessionToken, nil
}

// Logout мгновенно инвалидирует сессию в Redis
func (s *SessionService) Logout(sessionToken string) {
	s.redis.Del("session:" + sessionToken)
}

// ValidateSession проверяет сессию
func (s *SessionService) ValidateSession(sessionToken string) (*UserSessionData, bool) {
	return s.redis.Get("session:" + sessionToken)
}

func main() {
	redis := NewMockRedisClient()
	svc := NewSessionService(redis)

	fmt.Println("=== 1. Аутентификация пользователя (Вход в систему) ===")
	token, err := svc.Login("usr_5510", "lead@company.tech", "teamlead", 24*time.Hour)
	if err != nil {
		panic(err)
	}

	fmt.Printf("Выдан Session Token (32 байта энтропии):\n%s\n\n", token)

	// Проверка валидности
	fmt.Println("=== 2. Валидация сессии при обращении к API ===")
	session, ok := svc.ValidateSession(token)
	fmt.Printf("Сессия активна: %t\n", ok)
	sessJSON, _ := json.Marshal(session)
	fmt.Printf("Данные из Redis:\n%s\n\n", string(sessJSON))

	// Логаут
	fmt.Println("=== 3. Выход из системы (Logout) ===")
	svc.Logout(token)
	fmt.Println("Вызов: DEL session:<token>")

	_, okAfterLogout := svc.ValidateSession(token)
	fmt.Printf("Проверка сессии после Logout: активна = %t (Мгновенная блокировка!)\n", okAfterLogout)
}

package main

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"

	"golang.org/x/oauth2"
	"golang.org/x/oauth2/github"
)

type GitHubOAuthApp struct {
	config *oauth2.Config
}

func NewGitHubOAuthApp(clientID, clientSecret, redirectURL string) *GitHubOAuthApp {
	return &GitHubOAuthApp{
		config: &oauth2.Config{
			ClientID:     clientID,
			ClientSecret: clientSecret,
			Endpoint:     github.Endpoint,
			RedirectURL:  redirectURL,
			Scopes:       []string{"read:user", "user:email"},
		},
	}
}

// HandleLogin инициирует поток авторизации
func (app *GitHubOAuthApp) HandleLogin(w http.ResponseWriter, r *http.Request) {
	// 1. Генерируем 32 байта случайного CSRF state
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	state := hex.EncodeToString(b)

	// 2. Сохраняем state в защищенную Cookie
	cookie := &http.Cookie{
		Name:     "oauth_csrf_state",
		Value:    state,
		Expires:  time.Now().Add(10 * time.Minute),
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
	}
	http.SetCookie(w, cookie)

	// 3. Формируем URL перенаправления на GitHub
	redirectTarget := app.config.AuthCodeURL(state, oauth2.AccessTypeOffline)
	http.Redirect(w, r, redirectTarget, http.StatusTemporaryRedirect)
}

// HandleCallback валидирует state и обменивает code на Access Token
func (app *GitHubOAuthApp) HandleCallback(w http.ResponseWriter, r *http.Request) {
	// 1. Извлекаем и сверяем state
	stateCookie, err := r.Cookie("oauth_csrf_state")
	if err != nil {
		http.Error(w, "missing state cookie", http.StatusBadRequest)
		return
	}

	queryState := r.URL.Query().Get("state")
	if queryState == "" || subtle.ConstantTimeCompare([]byte(stateCookie.Value), []byte(queryState)) != 1 {
		http.Error(w, "CSRF State mismatch! Атака заблокирована!", http.StatusForbidden)
		return
	}

	// Очищаем использованную cookie
	http.SetCookie(w, &http.Cookie{Name: "oauth_csrf_state", MaxAge: -1, Path: "/"})

	code := r.URL.Query().Get("code")
	if code == "" {
		http.Error(w, "missing authorization code", http.StatusBadRequest)
		return
	}

	// 2. В продакшне: token, err := app.config.Exchange(r.Context(), code)
	// Эмулируем успешный результат обмена
	fmt.Fprintf(w, "✅ Успешный обмен! Код '%s' обменян на Access Token!", code)
}

func main() {
	app := NewGitHubOAuthApp("gh_client_id_12345", "gh_client_secret_67890", "http://localhost:8080/callback")

	// Тест 1: Запрос на /login
	reqLogin := httptest.NewRequest(http.MethodGet, "/login", nil)
	wLogin := httptest.NewRecorder()
	app.HandleLogin(wLogin, reqLogin)

	respLogin := wLogin.Result()
	cookies := respLogin.Cookies()
	var stateVal string
	for _, c := range cookies {
		if c.Name == "oauth_csrf_state" {
			stateVal = c.Value
		}
	}

	fmt.Println("=== 1. Эндпоинт /login (Генерация ссылки авторизации GitHub) ===")
	fmt.Printf("HTTP Код ответа: %d\n", respLogin.StatusCode)
	fmt.Printf("Location URL:    %s\n", respLogin.Header.Get("Location"))
	fmt.Printf("Установлен state: %s...\n\n", stateVal[:16])

	// Тест 2: Легитимный возврат от GitHub на /callback
	fmt.Println("=== 2. Легитимный /callback (с верным CSRF state) ===")
	cbURL := fmt.Sprintf("/callback?code=gh_auth_code_99182&state=%s", stateVal)
	reqCB := httptest.NewRequest(http.MethodGet, cbURL, nil)
	reqCB.AddCookie(&http.Cookie{Name: "oauth_csrf_state", Value: stateVal})
	wCB := httptest.NewRecorder()
	app.HandleCallback(wCB, reqCB)

	fmt.Printf("HTTP Код: %d\n", wCB.Code)
	fmt.Printf("Тело ответа: %s\n\n", wCB.Body.String())

	// Тест 3: Атака CSRF (несовпадение state)
	fmt.Println("=== 3. Атака подделки CSRF /callback ===")
	reqAttack := httptest.NewRequest(http.MethodGet, "/callback?code=evil_code&state=forged_state", nil)
	reqAttack.AddCookie(&http.Cookie{Name: "oauth_csrf_state", Value: stateVal})
	wAttack := httptest.NewRecorder()
	app.HandleCallback(wAttack, reqAttack)

	fmt.Printf("HTTP Код: %d\n", wAttack.Code)
	fmt.Printf("Тело ответа: %s\n", wAttack.Body.String())
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"sync"
	"time"
)

// AuthServer — симулятор OAuth2 сервера авторизации
type AuthServer struct {
	mu           sync.Mutex
	codes        map[string]AuthCode
	clients      map[string]string // client_id -> client_secret
	validTokens  map[string]string // access_token -> user_id
}

type AuthCode struct {
	UserID      string
	ClientID    string
	RedirectURI string
	ExpiresAt   time.Time
}

type TokenResponse struct {
	AccessToken  string `json:"access_token"`
	TokenType    string `json:"token_type"`
	ExpiresIn    int    `json:"expires_in"`
	RefreshToken string `json:"refresh_token,omitempty"`
}

func NewAuthServer() *AuthServer {
	return &AuthServer{
		codes:       make(map[string]AuthCode),
		clients:     map[string]string{"client-app-123": "secret-xyz-789"},
		validTokens: make(map[string]string),
	}
}

// Эндпоинт /token сервера авторизации
func (as *AuthServer) HandleToken(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Метод не поддерживается", http.StatusMethodNotAllowed)
		return
	}

	clientID := r.FormValue("client_id")
	clientSecret := r.FormValue("client_secret")
	code := r.FormValue("code")
	grantType := r.FormValue("grant_type")

	as.mu.Lock()
	defer as.mu.Unlock()

	// 1. Валидация клиента
	secret, ok := as.clients[clientID]
	if !ok || secret != clientSecret {
		http.Error(w, `{"error":"invalid_client"}`, http.StatusUnauthorized)
		return
	}

	if grantType != "authorization_code" {
		http.Error(w, `{"error":"unsupported_grant_type"}`, http.StatusBadRequest)
		return
	}

	// 2. Валидация и одноразовое потребление кода
	authCode, exists := as.codes[code]
	if !exists || time.Now().After(authCode.ExpiresAt) || authCode.ClientID != clientID {
		http.Error(w, `{"error":"invalid_grant"}`, http.StatusBadRequest)
		return
	}
	delete(as.codes, code) // Код ОБЯЗАН быть одноразовым!

	// 3. Выпуск токенов
	accessToken := fmt.Sprintf("at_%s_%d", authCode.UserID, time.Now().UnixNano())
	refreshToken := fmt.Sprintf("rt_%s_%d", authCode.UserID, time.Now().UnixNano())
	as.validTokens[accessToken] = authCode.UserID

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(TokenResponse{
		AccessToken:  accessToken,
		TokenType:    "Bearer",
		ExpiresIn:    3600,
		RefreshToken: refreshToken,
	})
}

func main() {
	as := NewAuthServer()
	authServerMux := http.NewServeMux()
	authServerMux.HandleFunc("/token", as.HandleToken)
	ts := httptest.NewServer(authServerMux)
	defer ts.Close()

	// 1. Инициация потока: сохранение кода на сервере авторизации
	authCodeValue := "sec_code_abc_999"
	as.mu.Lock()
	as.codes[authCodeValue] = AuthCode{
		UserID:      "usr_42",
		ClientID:    "client-app-123",
		RedirectURI: "https://myclient.com/callback",
		ExpiresAt:   time.Now().Add(60 * time.Second),
	}
	as.mu.Unlock()

	fmt.Println("=== 1. Front-channel: Сервер вернул редирект с кодом авторизации ===")
	fmt.Printf("Redirected code: %s, state: state_csrf_token_1\n", authCodeValue)

	// 2. Back-channel: Бэкенд клиента делает POST /token
	fmt.Println("\n=== 2. Back-channel: Бэкенд клиента обменивает code на токены ===")
	formData := url.Values{
		"grant_type":    {"authorization_code"},
		"code":          {authCodeValue},
		"client_id":     {"client-app-123"},
		"client_secret": {"secret-xyz-789"},
		"redirect_uri":  {"https://myclient.com/callback"},
	}

	resp, err := http.Post(ts.URL+"/token", "application/x-www-form-urlencoded", strings.NewReader(formData.Encode()))
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(resp.Body)
	fmt.Printf("HTTP Status: %d\n", resp.StatusCode)

	var tokenRes TokenResponse
	if err := json.Unmarshal(body, &tokenRes); err != nil {
		panic(err)
	}
	fmt.Printf("Access Token:  %s\n", tokenRes.AccessToken)
	fmt.Printf("Refresh Token: %s\n", tokenRes.RefreshToken)
	fmt.Printf("Expires In:    %d секунд\n", tokenRes.ExpiresIn)

	// 3. Попытка повторного использования кода (Replay Attack)
	fmt.Println("\n=== 3. Проверка защиты от повторного использования кода авторизации ===")
	resp2, _ := http.Post(ts.URL+"/token", "application/x-www-form-urlencoded", strings.NewReader(formData.Encode()))
	defer resp2.Body.Close()
	body2, _ := io.ReadAll(resp2.Body)
	fmt.Printf("Повторный обмен того же кода -> HTTP Status: %d, Body: %s\n", resp2.StatusCode, string(body2))
}

package main

import (
	"crypto/ed25519"
	"crypto/rand"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// PAE (Pre-Authentication Encoding) по спецификации PASETO RFC
func pae(pieces ...[]byte) []byte {
	count := len(pieces)
	buf := make([]byte, 8)
	binary.LittleEndian.PutUint64(buf, uint64(count))
	res := append([]byte{}, buf...)

	for _, p := range pieces {
		lenBuf := make([]byte, 8)
		binary.LittleEndian.PutUint64(lenBuf, uint64(len(p)))
		res = append(res, lenBuf...)
		res = append(res, p...)
	}
	return res
}

type PasetoClaims struct {
	Subject   string `json:"sub"`
	Role      string `json:"role"`
	ExpiresAt int64  `json:"exp"`
}

// SignV4Public — выпуск v4.public токена
func SignV4Public(claims PasetoClaims, privKey ed25519.PrivateKey) (string, error) {
	header := "v4.public."
	payloadJSON, err := json.Marshal(claims)
	if err != nil {
		return "", err
	}

	// PAE(header, payload, footer)
	m := pae([]byte(header), payloadJSON, []byte(""))
	sig := ed25519.Sign(privKey, m)

	// Токен = header + base64url(payload + sig)
	combined := append(payloadJSON, sig...)
	token := header + base64.RawURLEncoding.EncodeToString(combined)
	return token, nil
}

// VerifyV4Public — верификация v4.public токена публичным ключом
func VerifyV4Public(token string, pubKey ed25519.PublicKey) (*PasetoClaims, error) {
	header := "v4.public."
	if !strings.HasPrefix(token, header) {
		return nil, errors.New("неверный заголовок PASETO: ожидался v4.public.")
	}

	encoded := strings.TrimPrefix(token, header)
	raw, err := base64.RawURLEncoding.DecodeString(encoded)
	if err != nil {
		return nil, fmt.Errorf("ошибка base64: %w", err)
	}

	if len(raw) < ed25519.SignatureSize {
		return nil, errors.New("токен слишком короткий для подписи Ed25519")
	}

	payloadLen := len(raw) - ed25519.SignatureSize
	payload := raw[:payloadLen]
	sig := raw[payloadLen:]

	m := pae([]byte(header), payload, []byte(""))
	if !ed25519.Verify(pubKey, m, sig) {
		return nil, errors.New("криптографическая подпись Ed25519 невалидна!")
	}

	var claims PasetoClaims
	if err := json.Unmarshal(payload, &claims); err != nil {
		return nil, fmt.Errorf("ошибка парсинга claims: %w", err)
	}

	if time.Now().Unix() > claims.ExpiresAt {
		return nil, errors.New("срок действия токена истек")
	}

	return &claims, nil
}

func main() {
	// 1. Генерация легитимной пары Ed25519
	pubKey, privKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		panic(err)
	}

	claims := PasetoClaims{
		Subject:   "usr_engineer_42",
		Role:      "system_architect",
		ExpiresAt: time.Now().Add(1 * time.Hour).Unix(),
	}

	token, err := SignV4Public(claims, privKey)
	if err != nil {
		panic(err)
	}
	fmt.Printf("=== 1. Сгенерирован легитимный PASETO v4.public токен ===\n%s\n\n", token)

	// 2. Успешная валидация доверенным публичным ключом
	verifiedClaims, err := VerifyV4Public(token, pubKey)
	if err != nil {
		panic(err)
	}
	fmt.Printf("=== 2. Успешная верификация публичным ключом ===\nSubject: %s, Role: %s\n\n",
		verifiedClaims.Subject, verifiedClaims.Role)

	// 3. Попытка верификации чужим/поддельным публичным ключом
	otherPubKey, _, _ := ed25519.GenerateKey(rand.Reader)
	_, err = VerifyV4Public(token, otherPubKey)
	fmt.Printf("=== 3. Попытка проверки чужим публичным ключом ===\nРезультат: %v\n\n", err)

	// 4. Попытка подделки полезной нагрузки атакующим
	parts := strings.Split(token, ".")
	tamperedJSON := `{"sub":"usr_engineer_42","role":"super_admin","exp":9999999999}`
	sig := token[len("v4.public.")+len(base64.RawURLEncoding.EncodeToString([]byte(tamperedJSON))):]
	tamperedToken := "v4.public." + base64.RawURLEncoding.EncodeToString(append([]byte(tamperedJSON), []byte(sig)...))
	_, err = VerifyV4Public(tamperedToken, pubKey)
	fmt.Printf("=== 4. Попытка подделки роли до super_admin ===\nРезультат: %v\n", err)
	_ = parts
}

package main

import (
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"sync"
)

// GenerateCodeVerifier создает криптографический verifier (43-128 символов)
func GenerateCodeVerifier() (string, error) {
	b := make([]byte, 32) // 32 байта энтропии -> 43 символа base64url
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// ComputeCodeChallengeS256 вычисляет code_challenge = Base64URL(SHA256(verifier))
func ComputeCodeChallengeS256(verifier string) string {
	h := sha256.Sum256([]byte(verifier))
	return base64.RawURLEncoding.EncodeToString(h[:])
}

// ServerPKCE имитирует сервер авторизации с поддержкой RFC 7636
type ServerPKCE struct {
	mu            sync.Mutex
	authCodes     map[string]PKCECodeRecord
}

type PKCECodeRecord struct {
	Challenge       string
	ChallengeMethod string
	ClientID        string
}

func (s *ServerPKCE) IssueCode(clientID, challenge, method string) (string, error) {
	if method != "S256" {
		return "", errors.New("поддерживается исключительно метод S256")
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	code := "auth_code_" + base64.RawURLEncoding.EncodeToString([]byte(challenge[:8]))
	s.authCodes[code] = PKCECodeRecord{
		Challenge:       challenge,
		ChallengeMethod: method,
		ClientID:        clientID,
	}
	return code, nil
}

func (s *ServerPKCE) HandleToken(w http.ResponseWriter, r *http.Request) {
	code := r.FormValue("code")
	verifier := r.FormValue("code_verifier")

	s.mu.Lock()
	record, exists := s.authCodes[code]
	if exists {
		delete(s.authCodes, code) // одноразовое потребление
	}
	s.mu.Unlock()

	if !exists {
		http.Error(w, `{"error":"invalid_grant","error_description":"Неверный код"}`, http.StatusBadRequest)
		return
	}

	// Проверка PKCE
	expectedChallenge := ComputeCodeChallengeS256(verifier)
	if subtle.ConstantTimeCompare([]byte(expectedChallenge), []byte(record.Challenge)) != 1 {
		http.Error(w, `{"error":"invalid_grant","error_description":"PKCE verifier mismatch"}`, http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write([]byte(`{"access_token":"at_pkce_success_valid_token","token_type":"Bearer","expires_in":3600}`))
}

func main() {
	server := &ServerPKCE{authCodes: make(map[string]PKCECodeRecord)}
	mux := http.NewServeMux()
	mux.HandleFunc("/token", server.HandleToken)
	ts := httptest.NewServer(mux)
	defer ts.Close()

	// 1. Клиент генерирует пару PKCE
	verifier, err := GenerateCodeVerifier()
	if err != nil {
		panic(err)
	}
	challenge := ComputeCodeChallengeS256(verifier)

	fmt.Println("=== 1. Генерация PKCE параметров на клиенте ===")
	fmt.Printf("Code Verifier  (секрет клиента): %s (длина %d)\n", verifier, len(verifier))
	fmt.Printf("Code Challenge (отправляется в /auth): %s\n\n", challenge)

	// 2. Шаг /authorize: клиент получает код, сервер запоминает challenge
	code, err := server.IssueCode("mobile_app_ios", challenge, "S256")
	if err != nil {
		panic(err)
	}
	fmt.Printf("Сервер выдал Auth Code: %s\n\n", code)

	// 3. Злоумышленник перехватил code, но не знает verifier
	fmt.Println("=== 2. Атака: Вредоносное приложение пытается обменять code без verifier ===")
	badData := url.Values{"code": {code}, "code_verifier": {"wrong_guess_verifier_string_123"}}
	// Создаем второй код для атаки, чтобы не сжечь первый
	attackCode, _ := server.IssueCode("mobile_app_ios", challenge, "S256")
	badData.Set("code", attackCode)
	respBad, _ := http.Post(ts.URL+"/token", "application/x-www-form-urlencoded", strings.NewReader(badData.Encode()))
	defer respBad.Body.Close()
	fmt.Printf("Ответ сервера на атаку: HTTP Status %d (Запрос заблокирован!)\n\n", respBad.StatusCode)

	// 4. Легитимный клиент обменивает code с правильным verifier
	fmt.Println("=== 3. Легитимный клиент отправляет правильный code_verifier ===")
	goodData := url.Values{"code": {code}, "code_verifier": {verifier}}
	respGood, _ := http.Post(ts.URL+"/token", "application/x-www-form-urlencoded", strings.NewReader(goodData.Encode()))
	defer respGood.Body.Close()
	fmt.Printf("Ответ сервера легитимному клиенту: HTTP Status %d (Токен получен!)\n", respGood.StatusCode)
}

package main

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

// GenerateRandomState создает криптографический nonce (32 байта)
func GenerateRandomState() (string, error) {
	b := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// LoginHandler — начало OAuth потока
func LoginHandler(w http.ResponseWriter, r *http.Request) {
	state, err := GenerateRandomState()
	if err != nil {
		http.Error(w, "Ошибка генерации state", http.StatusInternalServerError)
		return
	}

	// Сохраняем state в защищенную куку с коротким TTL (5 минут)
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		Path:     "/callback",
		MaxAge:   300,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode, // Обязательно Lax для внешних редиректов!
	})

	authURL := fmt.Sprintf("https://idp.example.com/oauth/authorize?client_id=my_client&response_type=code&state=%s", state)
	http.Redirect(w, r, authURL, http.StatusFound)
}

// CallbackHandler — обработка возврата от IdP
func CallbackHandler(w http.ResponseWriter, r *http.Request) {
	receivedState := r.URL.Query().Get("state")
	code := r.URL.Query().Get("code")

	if receivedState == "" || code == "" {
		http.Error(w, "Отсутствуют обязательные параметры", http.StatusBadRequest)
		return
	}

	cookie, err := r.Cookie("oauth_state")
	if err != nil || cookie.Value == "" {
		http.Error(w, "CSRF обнаружен: отсутствует oauth_state кука!", http.StatusForbidden)
		return
	}

	// Защита от timing-атак при сравнении строк
	if subtle.ConstantTimeCompare([]byte(receivedState), []byte(cookie.Value)) != 1 {
		http.Error(w, "CSRF атака заблокирована: state не совпадает с сессией!", http.StatusForbidden)
		return
	}

	// Очищаем куку после успешного использования (one-time use)
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    "",
		Path:     "/callback",
		MaxAge:   -1,
		HttpOnly: true,
	})

	w.WriteHeader(http.StatusOK)
	_, _ = fmt.Fprintf(w, "Успешная валидация state! Код авторизации: %s принят к обмену.", code)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/login", LoginHandler)
	mux.HandleFunc("/callback", CallbackHandler)

	ts := httptest.NewServer(mux)
	defer ts.Close()

	// 1. Легитимный пользователь инициирует вход
	reqLogin, _ := http.NewRequest("GET", ts.URL+"/login", nil)
	wLogin := httptest.NewRecorder()
	LoginHandler(wLogin, reqLogin)

	cookie := wLogin.Result().Cookies()[0]
	redirectLocation := wLogin.Header().Get("Location")
	fmt.Println("=== 1. Клиент инициировал логин ===")
	fmt.Printf("Выставлена Cookie: %s=%s\n", cookie.Name, cookie.Value)
	fmt.Printf("Redirect URL:      %s\n\n", redirectLocation)

	// 2. Легитимный возврат: state в query совпадает с кукой
	reqCallbackGood, _ := http.NewRequest("GET", ts.URL+"/callback?code=good_code_123&state="+cookie.Value, nil)
	reqCallbackGood.AddCookie(cookie)
	wCallbackGood := httptest.NewRecorder()
	CallbackHandler(wCallbackGood, reqCallbackGood)
	fmt.Println("=== 2. Легитимный возврат (Valid State) ===")
	fmt.Printf("HTTP Status: %d, Ответ: %s\n\n", wCallbackGood.Code, wCallbackGood.Body.String())

	// 3. Атака Login CSRF: жертве подсунули запрос с чужим кодом и чужим state
	reqCallbackCSRF, _ := http.NewRequest("GET", ts.URL+"/callback?code=attacker_code_666&state=attacker_state_fake", nil)
	reqCallbackCSRF.AddCookie(cookie) // У жертвы в куке ее собственный state, а в query — атакующего!
	wCallbackCSRF := httptest.NewRecorder()
	CallbackHandler(wCallbackCSRF, reqCallbackCSRF)
	fmt.Println("=== 3. Атака Login CSRF (State mismatch) ===")
	fmt.Printf("HTTP Status: %d, Ошибка: %s\n", wCallbackCSRF.Code, wCallbackCSRF.Body.String())
}

package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"sync"
	"time"
)

const (
	HeaderAccessKey = "X-Access-Key"
	HeaderTimestamp = "X-Timestamp"
	HeaderNonce     = "X-Nonce"
	HeaderSignature = "X-Signature"
	MaxTimeSkewSec  = 300 // 5 минут
)

type SigAuthMiddleware struct {
	secretStore map[string]string // AccessKey -> SecretKey
	nonceCache  sync.Map          // Nonce -> ExpireTimestamp
}

func NewSigAuthMiddleware() *SigAuthMiddleware {
	return &SigAuthMiddleware{
		secretStore: map[string]string{"svc_billing": "super_secret_signing_key_42"},
	}
}

// BuildCanonicalString строит детерминированную строку для подписи
func BuildCanonicalString(method, path string, timestamp int64, nonce string, body []byte) string {
	bodyHash := sha256.Sum256(body)
	return fmt.Sprintf("%s\n%s\n%d\n%s\n%x", method, path, timestamp, nonce, bodyHash)
}

func (m *SigAuthMiddleware) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		accessKey := r.Header.Get(HeaderAccessKey)
		tsStr := r.Header.Get(HeaderTimestamp)
		nonce := r.Header.Get(HeaderNonce)
		clientSig := r.Header.Get(HeaderSignature)

		// 1. Проверка наличия заголовков
		if accessKey == "" || tsStr == "" || nonce == "" || clientSig == "" {
			http.Error(w, "Отсутствуют обязательные заголовки подписи", http.StatusUnauthorized)
			return
		}

		secretKey, exists := m.secretStore[accessKey]
		if !exists {
			http.Error(w, "Неверный Access Key", http.StatusUnauthorized)
			return
		}

		// 2. Проверка временного окна (защита от устаревших запросов)
		reqTime, err := strconv.ParseInt(tsStr, 10, 64)
		if err != nil || time.Now().Unix()-reqTime > MaxTimeSkewSec || reqTime-time.Now().Unix() > MaxTimeSkewSec {
			http.Error(w, "Временная метка запроса устарела или находится в будущем", http.StatusUnauthorized)
			return
		}

		// 3. Защита от Replay-атак (Nonce cache)
		if _, loaded := m.nonceCache.LoadOrStore(nonce, reqTime); loaded {
			http.Error(w, "Обнаружена Replay-атака: данный Nonce уже использован!", http.StatusConflict)
			return
		}

		// 4. Чтение и восстановление тела запроса
		body, _ := io.ReadAll(r.Body)
		r.Body = io.NopCloser(bytes.NewReader(body))

		// 5. Вычисление ожидаемой HMAC подписи
		canonical := BuildCanonicalString(r.Method, r.URL.Path, reqTime, nonce, body)
		h := hmac.New(sha256.New, []byte(secretKey))
		h.Write([]byte(canonical))
		expectedSig := hex.EncodeToString(h.Sum(nil))

		// 6. Сравнение подписей в константное время
		if subtle.ConstantTimeCompare([]byte(clientSig), []byte(expectedSig)) != 1 {
			http.Error(w, "Неверная криптографическая подпись запроса", http.StatusForbidden)
			return
		}

		next.ServeHTTP(w, r)
	})
}

// SignRequest подписывает исходящий запрос на клиенте
func SignRequest(req *http.Request, accessKey, secretKey string, body []byte) {
	now := time.Now().Unix()
	nonce := fmt.Sprintf("nonce_%d_%s", now, hex.EncodeToString(body[:min(len(body), 4)]))

	req.Header.Set(HeaderAccessKey, accessKey)
	req.Header.Set(HeaderTimestamp, strconv.FormatInt(now, 10))
	req.Header.Set(HeaderNonce, nonce)

	canonical := BuildCanonicalString(req.Method, req.URL.Path, now, nonce, body)
	h := hmac.New(sha256.New, []byte(secretKey))
	h.Write([]byte(canonical))
	sig := hex.EncodeToString(h.Sum(nil))

	req.Header.Set(HeaderSignature, sig)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func main() {
	authMw := NewSigAuthMiddleware()
	targetHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"success","action":"payment_processed"}`))
	})

	server := httptest.NewServer(authMw.Middleware(targetHandler))
	defer server.Close()

	payload := []byte(`{"account":"acc_1001","amount":5000}`)

	// 1. Легитимный подписанный запрос
	req1, _ := http.NewRequest("POST", server.URL+"/api/v1/charge", bytes.NewReader(payload))
	SignRequest(req1, "svc_billing", "super_secret_signing_key_42", payload)
	resp1, _ := http.DefaultClient.Do(req1)
	body1, _ := io.ReadAll(resp1.Body)
	resp1.Body.Close()
	fmt.Printf("=== 1. Легитимный запрос ===\nHTTP Status: %d, Body: %s\n\n", resp1.StatusCode, string(body1))

	// 2. Попытка модификации тела запроса (MITM Tampering)
	tamperedPayload := []byte(`{"account":"acc_1001","amount":999999}`)
	reqTampered, _ := http.NewRequest("POST", server.URL+"/api/v1/charge", bytes.NewReader(tamperedPayload))
	SignRequest(reqTampered, "svc_billing", "super_secret_signing_key_42", payload) // подпись была для 5000!
	respTampered, _ := http.DefaultClient.Do(reqTampered)
	bodyTampered, _ := io.ReadAll(respTampered.Body)
	respTampered.Body.Close()
	fmt.Printf("=== 2. Модификация тела запроса злоумышленником ===\nHTTP Status: %d, Ошибка: %s\n\n", respTampered.StatusCode, string(bodyTampered))

	// 3. Replay-атака: злоумышленник перехватил и повторно отправляет req1
	reqReplay, _ := http.NewRequest("POST", server.URL+"/api/v1/charge", bytes.NewReader(payload))
	reqReplay.Header = req1.Header.Clone()
	respReplay, _ := http.DefaultClient.Do(reqReplay)
	bodyReplay, _ := io.ReadAll(respReplay.Body)
	respReplay.Body.Close()
	fmt.Printf("=== 3. Повторная отправка идентичного запроса (Replay) ===\nHTTP Status: %d, Ошибка: %s\n", respReplay.StatusCode, string(bodyReplay))
}

package main

import (
	"crypto/ed25519"
	"crypto/rand"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// PAE кодирование для устранения атак изменения длины
func pae(pieces ...[]byte) []byte {
	buf := make([]byte, 8)
	binary.LittleEndian.PutUint64(buf, uint64(len(pieces)))
	out := append([]byte{}, buf...)
	for _, piece := range pieces {
		lenBuf := make([]byte, 8)
		binary.LittleEndian.PutUint64(lenBuf, uint64(len(piece)))
		out = append(out, lenBuf...)
		out = append(out, piece...)
	}
	return out
}

type UserClaims struct {
	Issuer    string    `json:"iss"`
	Subject   string    `json:"sub"`
	IssuedAt  time.Time `json:"iat"`
	ExpiresAt time.Time `json:"exp"`
	Role      string    `json:"role"`
}

// CreateV4PublicToken создает подписанный PASETO v4 токен
func CreateV4PublicToken(claims UserClaims, privKey ed25519.PrivateKey) (string, error) {
	header := "v4.public."
	payload, err := json.Marshal(claims)
	if err != nil {
		return "", err
	}

	// Вычисление подписи Ed25519 над PAE(header, payload, footer)
	m := pae([]byte(header), payload, []byte(""))
	sig := ed25519.Sign(privKey, m)

	tokenBody := append(payload, sig...)
	return header + base64.RawURLEncoding.EncodeToString(tokenBody), nil
}

// ParseAndVerifyV4Public валидирует токен
func ParseAndVerifyV4Public(token string, pubKey ed25519.PublicKey) (*UserClaims, error) {
	const header = "v4.public."
	if !strings.HasPrefix(token, header) {
		return nil, errors.New("неверный формат токена: ожидался заголовок v4.public.")
	}

	raw, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(token, header))
	if err != nil {
		return nil, errors.New("ошибка декодирования Base64URL")
	}

	if len(raw) < ed25519.SignatureSize {
		return nil, errors.New("длина токена меньше размера подписи Ed25519 (64 байта)")
	}

	payloadLen := len(raw) - ed25519.SignatureSize
	payload := raw[:payloadLen]
	sig := raw[payloadLen:]

	m := pae([]byte(header), payload, []byte(""))
	if !ed25519.Verify(pubKey, m, sig) {
		return nil, errors.New("цифровая подпись Ed25519 невалидна")
	}

	var claims UserClaims
	if err := json.Unmarshal(payload, &claims); err != nil {
		return nil, errors.New("ошибка десериализации claims")
	}

	if time.Now().After(claims.ExpiresAt) {
		return nil, errors.New("срок действия токена истек")
	}

	return &claims, nil
}

func main() {
	pubKey, privKey, _ := ed25519.GenerateKey(rand.Reader)

	claims := UserClaims{
		Issuer:    "https://auth.company.corp",
		Subject:   "usr_developer_77",
		IssuedAt:  time.Now(),
		ExpiresAt: time.Now().Add(30 * time.Minute),
		Role:      "platform_engineer",
	}

	token, err := CreateV4PublicToken(claims, privKey)
	if err != nil {
		panic(err)
	}

	fmt.Println("=== 1. Выпущенный токен PASETO v4.public ===")
	fmt.Println(token)

	// Валидация легитимного токена
	verified, err := ParseAndVerifyV4Public(token, pubKey)
	if err != nil {
		panic(err)
	}
	fmt.Printf("\n=== 2. Успешная валидация ===\nUser: %s, Role: %s, Exp: %s\n",
		verified.Subject, verified.Role, verified.ExpiresAt.Format(time.RFC3339))

	// Демонстрация защиты: попытка скормить токен с поддельным заголовком
	fakeToken := "v4.local." + strings.TrimPrefix(token, "v4.public.")
	_, errFake := ParseAndVerifyV4Public(fakeToken, pubKey)
	fmt.Printf("\n=== 3. Защита от путаницы протоколов ===\nПопытка подсунуть v4.local: %v\n", errFake)
}

package main

import (
	"crypto/subtle"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"sync"
	"time"
)

type ClientApp struct {
	Secret        string
	AllowedScopes []string
}

type TokenResponse struct {
	AccessToken string `json:"access_token"`
	TokenType   string `json:"token_type"`
	ExpiresIn   int    `json:"expires_in"`
	Scope       string `json:"scope"`
}

type M2MAuthServer struct {
	mu      sync.RWMutex
	clients map[string]ClientApp
	tokens  map[string]int64 // token -> exp
}

func (s *M2MAuthServer) HandleToken(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}

	clientID, clientSecret, ok := r.BasicAuth()
	if !ok {
		// Поддержка передачи через тело формы
		clientID = r.FormValue("client_id")
		clientSecret = r.FormValue("client_secret")
	}

	s.mu.RLock()
	client, exists := s.clients[clientID]
	s.mu.RUnlock()

	if !exists || subtle.ConstantTimeCompare([]byte(client.Secret), []byte(clientSecret)) != 1 {
		http.Error(w, `{"error":"invalid_client"}`, http.StatusUnauthorized)
		return
	}

	if r.FormValue("grant_type") != "client_credentials" {
		http.Error(w, `{"error":"unsupported_grant_type"}`, http.StatusBadRequest)
		return
	}

	reqScope := r.FormValue("scope")
	tokenValue := fmt.Sprintf("m2m_token_%s_%d", clientID, time.Now().UnixNano())

	s.mu.Lock()
	s.tokens[tokenValue] = time.Now().Add(3600 * time.Second).Unix()
	s.mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(TokenResponse{
		AccessToken: tokenValue,
		TokenType:   "Bearer",
		ExpiresIn:   3600,
		Scope:       reqScope,
	})
}

// M2MClient — потокобезопасный клиент с кэшированием токена
type M2MClient struct {
	mu           sync.Mutex
	tokenURL     string
	clientID     string
	clientSecret string
	cachedToken  string
	expiresAt    time.Time
}

func (c *M2MClient) GetToken() (string, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	// Если токен еще валиден с запасом в 30 секунд — возвращаем из кэша
	if c.cachedToken != "" && time.Now().Add(30*time.Second).Before(c.expiresAt) {
		return c.cachedToken, nil
	}

	form := url.Values{
		"grant_type": {"client_credentials"},
		"scope":      {"payments.write"},
	}

	req, _ := http.NewRequest("POST", c.tokenURL, strings.NewReader(form.Encode()))
	req.SetBasicAuth(c.clientID, c.clientSecret)
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return "", fmt.Errorf("auth failed: %s", string(body))
	}

	var tr TokenResponse
	if err := json.NewDecoder(resp.Body).Decode(&tr); err != nil {
		return "", err
	}

	c.cachedToken = tr.AccessToken
	c.expiresAt = time.Now().Add(time.Duration(tr.ExpiresIn) * time.Second)
	return c.cachedToken, nil
}

func main() {
	server := &M2MAuthServer{
		clients: map[string]ClientApp{
			"payment_worker": {
				Secret:        "sec_corp_payments_991",
				AllowedScopes: []string{"payments.write", "reports.read"},
			},
		},
		tokens: make(map[string]int64),
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/oauth/token", server.HandleToken)
	ts := httptest.NewServer(mux)
	defer ts.Close()

	client := &M2MClient{
		tokenURL:     ts.URL + "/oauth/token",
		clientID:     "payment_worker",
		clientSecret: "sec_corp_payments_991",
	}

	// 1. Первый запрос: выпуск токена
	tok1, err := client.GetToken()
	if err != nil {
		panic(err)
	}
	fmt.Printf("=== 1. Получен первый токен от Auth Server ===\nToken: %s\n\n", tok1)

	// 2. Второй запрос: возврат из кэша памяти без сетевого вызова
	tok2, _ := client.GetToken()
	fmt.Printf("=== 2. Второй вызов: получен токен из локального кэша ===\nToken: %s\nTokens Equal: %v\n\n",
		tok2, tok1 == tok2)

	// 3. Попытка запроса с неверным секретом
	badClient := &M2MClient{
		tokenURL:     ts.URL + "/oauth/token",
		clientID:     "payment_worker",
		clientSecret: "wrong_hacker_secret",
	}
	_, errBad := badClient.GetToken()
	fmt.Printf("=== 3. Попытка входа с неверным секретом ===\nОшибка: %v\n", errBad)
}

package main

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
)

const StateCookieName = "oauth_csrf_state"

// GenerateOAuthState генерирует 256 бит криптографической случайности
func GenerateOAuthState() string {
	b := make([]byte, 32)
	_, _ = io.ReadFull(rand.Reader, b)
	return base64.RawURLEncoding.EncodeToString(b)
}

// HandlerLogin инициирует OAuth flow с установкой куки
func HandlerLogin(w http.ResponseWriter, r *http.Request) {
	state := GenerateOAuthState()

	// Установка защищенной куки
	cookie := &http.Cookie{
		Name:     StateCookieName,
		Value:    state,
		Path:     "/callback",
		MaxAge:   300, // 5 минут
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode, // Обязательно Lax для внешних 302-редиректов!
	}
	http.SetCookie(w, cookie)

	// Формирование URL провайдера (GitHub/Google)
	authURL := fmt.Sprintf("https://github.com/login/oauth/authorize?client_id=client_123&state=%s", url.QueryEscape(state))
	http.Redirect(w, r, authURL, http.StatusTemporaryRedirect)
}

// HandlerCallback проверяет возврат от провайдера
func HandlerCallback(w http.ResponseWriter, r *http.Request) {
	queryState := r.URL.Query().Get("state")
	code := r.URL.Query().Get("code")

	cookie, err := r.Cookie(StateCookieName)
	if err != nil || cookie.Value == "" {
		http.Error(w, "CSRF Error: State cookie отсутствует", http.StatusBadRequest)
		return
	}

	// Сравнение за константное время
	if subtle.ConstantTimeCompare([]byte(queryState), []byte(cookie.Value)) != 1 {
		http.Error(w, "CSRF Error: Несовпадение state параметра!", http.StatusForbidden)
		return
	}

	// Инвалидация одноразовой куки
	http.SetCookie(w, &http.Cookie{
		Name:     StateCookieName,
		Value:    "",
		Path:     "/callback",
		MaxAge:   -1,
		HttpOnly: true,
		Secure:   true,
	})

	w.WriteHeader(http.StatusOK)
	_, _ = fmt.Fprintf(w, "Успешная авторизация! Code: %s", code)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/login", HandlerLogin)
	mux.HandleFunc("/callback", HandlerCallback)

	ts := httptest.NewServer(mux)
	defer ts.Close()

	// 1. Моделирование /login
	recLogin := httptest.NewRecorder()
	reqLogin, _ := http.NewRequest("GET", "/login", nil)
	HandlerLogin(recLogin, reqLogin)

	cookies := recLogin.Result().Cookies()
	var stateCookie *http.Cookie
	for _, c := range cookies {
		if c.Name == StateCookieName {
			stateCookie = c
			break
		}
	}

	fmt.Println("=== 1. Инициация входа через GitHub ===")
	fmt.Printf("State Cookie Name:     %s\n", stateCookie.Name)
	fmt.Printf("State Cookie HttpOnly: %v\n", stateCookie.HttpOnly)
	fmt.Printf("State Cookie SameSite: %v (LaxMode)\n", stateCookie.SameSite == http.SameSiteLaxMode)
	fmt.Printf("State Cookie Value:    %s\n\n", stateCookie.Value)

	// 2. Успешный callback с совпадающим state
	recGood := httptest.NewRecorder()
	reqGood, _ := http.NewRequest("GET", "/callback?code=gh_code_888&state="+stateCookie.Value, nil)
	reqGood.AddCookie(stateCookie)
	HandlerCallback(recGood, reqGood)

	fmt.Println("=== 2. Успешный Callback от GitHub ===")
	fmt.Printf("Status: %d, Body: %s\n\n", recGood.Code, recGood.Body.String())

	// 3. Атака Login CSRF: атакующий пытается отправить запрос с левым state
	recBad := httptest.NewRecorder()
	reqBad, _ := http.NewRequest("GET", "/callback?code=gh_code_888&state=attacker_fake_state", nil)
	reqBad.AddCookie(stateCookie)
	HandlerCallback(recBad, reqBad)

	fmt.Println("=== 3. Атака Login CSRF с чужим State ===")
	fmt.Printf("Status: %d, Body: %s\n", recBad.Code, recBad.Body.String())
}

package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"sync"
	"time"
)

type DeviceSession struct {
	DeviceCode string
	UserCode   string
	Approved   bool
	ExpiresAt  time.Time
}

type DeviceAuthServer struct {
	mu       sync.Mutex
	sessions map[string]*DeviceSession // device_code -> session
	userMap  map[string]*DeviceSession // user_code -> session
}

func NewDeviceAuthServer() *DeviceAuthServer {
	return &DeviceAuthServer{
		sessions: make(map[string]*DeviceSession),
		userMap:  make(map[string]*DeviceSession),
	}
}

// 1. Эндпоинт /device/code
func (s *DeviceAuthServer) HandleDeviceCode(w http.ResponseWriter, r *http.Request) {
	b := make([]byte, 16)
	_, _ = io.ReadFull(rand.Reader, b)
	deviceCode := hex.EncodeToString(b)
	userCode := fmt.Sprintf("%04d-%04d", time.Now().UnixNano()%10000, (time.Now().UnixNano()/10000)%10000)

	session := &DeviceSession{
		DeviceCode: deviceCode,
		UserCode:   userCode,
		Approved:   false,
		ExpiresAt:  time.Now().Add(10 * time.Minute),
	}

	s.mu.Lock()
	s.sessions[deviceCode] = session
	s.userMap[userCode] = session
	s.mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"device_code":      deviceCode,
		"user_code":        userCode,
		"verification_uri": "https://example.com/activate",
		"expires_in":       600,
		"interval":         1,
	})
}

// 2. Эндпоинт /token (Polling клиентом)
func (s *DeviceAuthServer) HandleToken(w http.ResponseWriter, r *http.Request) {
	deviceCode := r.FormValue("device_code")

	s.mu.Lock()
	session, exists := s.sessions[deviceCode]
	s.mu.Unlock()

	if !exists || time.Now().After(session.ExpiresAt) {
		http.Error(w, `{"error":"expired_token"}`, http.StatusBadRequest)
		return
	}

	if !session.Approved {
		http.Error(w, `{"error":"authorization_pending"}`, http.StatusBadRequest)
		return
	}

	// Авторизовано! Удаляем сессию и отдаем токен
	s.mu.Lock()
	delete(s.sessions, deviceCode)
	delete(s.userMap, session.UserCode)
	s.mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(map[string]interface{}{
		"access_token": "at_tv_device_success_token_42",
		"token_type":   "Bearer",
		"expires_in":   3600,
	})
}

// 3. Эндпоинт /activate (Пользователь подтверждает код в браузере)
func (s *DeviceAuthServer) ApproveUserCode(userCode string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	session, exists := s.userMap[userCode]
	if !exists || time.Now().After(session.ExpiresAt) {
		return false
	}
	session.Approved = true
	return true
}

func main() {
	server := NewDeviceAuthServer()
	mux := http.NewServeMux()
	mux.HandleFunc("/device/code", server.HandleDeviceCode)
	mux.HandleFunc("/token", server.HandleToken)
	ts := httptest.NewServer(mux)
	defer ts.Close()

	// Шаг 1: CLI утилита делает запрос на получение кодов
	resp, _ := http.Post(ts.URL+"/device/code", "application/x-www-form-urlencoded", nil)
	var initData map[string]interface{}
	_ = json.NewDecoder(resp.Body).Decode(&initData)
	resp.Body.Close()

	deviceCode := initData["device_code"].(string)
	userCode := initData["user_code"].(string)
	uri := initData["verification_uri"].(string)

	fmt.Println("=== 1. CLI Устройство запросило авторизацию ===")
	fmt.Printf("Перейдите на: %s\n", uri)
	fmt.Printf("Введите код:   %s\n\n", userCode)

	// Шаг 2: Имитация фонового подтверждения пользователем через 50 мс
	go func() {
		time.Sleep(50 * time.Millisecond)
		fmt.Println(">>> [Пользователь открыл телефон и ввел код в браузере!]")
		server.ApproveUserCode(userCode)
	}()

	// Шаг 3: CLI опрашивает сервер (polling)
	fmt.Println("=== 2. CLI начинает поллинг сервера ===")
	for attempt := 1; attempt <= 5; attempt++ {
		form := url.Values{"device_code": {deviceCode}, "grant_type": {"urn:ietf:params:oauth:grant-type:device_code"}}
		tResp, _ := http.Post(ts.URL+"/token", "application/x-www-form-urlencoded", strings.NewReader(form.Encode()))
		body, _ := io.ReadAll(tResp.Body)
		tResp.Body.Close()

		if tResp.StatusCode == http.StatusOK {
			fmt.Printf("Попытка #%d -> УСПЕХ! Ответ: %s\n", attempt, string(body))
			break
		} else {
			fmt.Printf("Попытка #%d -> Сервер ожидает: %s\n", attempt, string(body))
		}
		time.Sleep(30 * time.Millisecond)
	}
}

package main

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"sync"
	"time"
)

type TokenFamily struct {
	FamilyID       string
	UserID         string
	CurrentToken   string
	ConsumedTokens map[string]time.Time // токены, которые уже были успешно ротированы
	IsRevoked      bool
}

type TokenService struct {
	mu       sync.Mutex
	families map[string]*TokenFamily // FamilyID -> Family
	tokenMap map[string]string       // RefreshToken -> FamilyID
}

func NewTokenService() *TokenService {
	return &TokenService{
		families: make(map[string]*TokenFamily),
		tokenMap: make(map[string]string),
	}
}

func generateToken(prefix string) string {
	b := make([]byte, 16)
	_, _ = io.ReadFull(rand.Reader, b)
	return fmt.Sprintf("%s_%s", prefix, hex.EncodeToString(b))
}

// IssueInitialSession создает новую семью токенов при логине
func (s *TokenService) IssueInitialSession(userID string) (accessToken, refreshToken string) {
	s.mu.Lock()
	defer s.mu.Unlock()

	familyID := generateToken("fam")
	refreshToken = generateToken("rt")
	accessToken = generateToken("at")

	family := &TokenFamily{
		FamilyID:       familyID,
		UserID:         userID,
		CurrentToken:   refreshToken,
		ConsumedTokens: make(map[string]time.Time),
		IsRevoked:      false,
	}

	s.families[familyID] = family
	s.tokenMap[refreshToken] = familyID
	return accessToken, refreshToken
}

// RotateToken выполняет одноразовую ротацию Refresh токена
func (s *TokenService) RotateToken(oldRefreshToken string) (newAccess, newRefresh string, err error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	familyID, exists := s.tokenMap[oldRefreshToken]
	if !exists {
		return "", "", errors.New("неизвестный refresh токен")
	}

	family := s.families[familyID]

	// 1. Проверка: семья уже была отозвана
	if family.IsRevoked {
		return "", "", errors.New("сессия полностью заблокирована из-за подозрительной активности")
	}

	// 2. ДЕТЕКЦИЯ ПОВТОРНОГО ИСПОЛЬЗОВАНИЯ (REPLAY ATTACK)
	if _, wasConsumed := family.ConsumedTokens[oldRefreshToken]; wasConsumed {
		// КРИТИЧЕСКИЙ ИНЦИДЕНТ: Кто-то пытается использовать старый токен!
		family.IsRevoked = true // Отзываем ВСЮ семью немедленно!
		return "", "", fmt.Errorf("SECURITY ALERT: Обнаружено повторное использование токена %s! Вся семья %s аннулирована!", oldRefreshToken, familyID)
	}

	// 3. Проверка: передан ли текущий валидный токен
	if family.CurrentToken != oldRefreshToken {
		family.IsRevoked = true
		return "", "", errors.New("рассинхронизация токенов: сессия аннулирована")
	}

	// 4. Успешная ротация: переводим старый токен в статус использованных
	family.ConsumedTokens[oldRefreshToken] = time.Now()
	newRefresh = generateToken("rt")
	newAccess = generateToken("at")

	family.CurrentToken = newRefresh
	s.tokenMap[newRefresh] = familyID

	return newAccess, newRefresh, nil
}

func main() {
	svc := NewTokenService()

	// 1. Первичная авторизация пользователя
	at1, rt1 := svc.IssueInitialSession("usr_alice_42")
	fmt.Println("=== 1. Успешный логин пользователя ===")
	fmt.Printf("Access Token 1:  %s\n", at1)
	fmt.Printf("Refresh Token 1: %s\n\n", rt1)

	// 2. Легитимное обновление токена (первая ротация)
	at2, rt2, err := svc.RotateToken(rt1)
	if err != nil {
		panic(err)
	}
	fmt.Println("=== 2. Первая ротация (Легитимный клиент) ===")
	fmt.Printf("Access Token 2:  %s\n", at2)
	fmt.Printf("Refresh Token 2: %s (rt1 теперь инвалидирован!)\n\n", rt2)

	// 3. Атака злоумышленника: попытка повторного использования перехваченного rt1
	fmt.Println("=== 3. Атака Replay: Злоумышленник пытается использовать старый rt1 ===")
	_, _, errReplay := svc.RotateToken(rt1)
	fmt.Printf("Результат: %v\n\n", errReplay)

	// 4. Проверка: легитимный клиент пытается использовать свой rt2
	fmt.Println("=== 4. Попытка легитимного клиента обновить rt2 после инцидента ===")
	_, _, errVictim := svc.RotateToken(rt2)
	fmt.Printf("Результат: %v (Клиент защищен, сессия принудительно завершена!)\n", errVictim)
}

package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

type contextKey string

const AuthContextKey contextKey = "auth_claims"

type AuthContext struct {
	Subject string
	Scopes  map[string]bool
}

// DummyTokenAuthMiddleware имитирует парсинг токена и извлечение scopes
func DummyTokenAuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if !strings.HasPrefix(authHeader, "Bearer ") {
			http.Error(w, `{"error":"unauthorized"}`, http.StatusUnauthorized)
			return
		}

		token := strings.TrimPrefix(authHeader, "Bearer ")
		var scopes []string
		var sub string

		// Имитация декодирования разных тестовых токенов
		switch token {
		case "read_only_token":
			sub = "usr_reader"
			scopes = []string{"read:users", "read:posts"}
		case "admin_token":
			sub = "usr_admin"
			scopes = []string{"read:users", "write:posts", "delete:posts"}
		default:
			http.Error(w, `{"error":"invalid_token"}`, http.StatusUnauthorized)
			return
		}

		scopeMap := make(map[string]bool)
		for _, s := range scopes {
			scopeMap[s] = true
		}

		ctx := context.WithValue(r.Context(), AuthContextKey, &AuthContext{
			Subject: sub,
			Scopes:  scopeMap,
		})
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

// RequireScopes — middleware для проверки необходимых привилегий (RFC 6750)
func RequireScopes(requiredScopes ...string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			authCtx, ok := r.Context().Value(AuthContextKey).(*AuthContext)
			if !ok || authCtx == nil {
				w.Header().Set("WWW-Authenticate", `Bearer error="invalid_token"`)
				http.Error(w, `{"error":"unauthorized"}`, http.StatusUnauthorized)
				return
			}

			// Проверяем наличие всех требуемых скоупов (AND logic)
			var missing []string
			for _, required := range requiredScopes {
				if !authCtx.Scopes[required] {
					missing = append(missing, required)
				}
			}

			if len(missing) > 0 {
				w.Header().Set("WWW-Authenticate", fmt.Sprintf(`Bearer error="insufficient_scope", scope="%s"`, strings.Join(requiredScopes, " ")))
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(http.StatusForbidden)
				_, _ = fmt.Fprintf(w, `{"error":"forbidden","missing_scopes":%q}`, missing)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}

func main() {
	mux := http.NewServeMux()

	// Публичный защищенный маршрут на чтение
	readHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"data":["user1","user2"]}`))
	})
	mux.Handle("/users", DummyTokenAuthMiddleware(RequireScopes("read:users")(readHandler)))

	// Маршрут на запись, требующий write:posts
	writeHandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusCreated)
		_, _ = w.Write([]byte(`{"status":"post_created"}`))
	})
	mux.Handle("/posts/create", DummyTokenAuthMiddleware(RequireScopes("write:posts")(writeHandler)))

	ts := httptest.NewServer(mux)
	defer ts.Close()

	// 1. Попытка создания поста с read-only токеном
	fmt.Println("=== 1. Попытка записи с токеном read_only_token ===")
	req1, _ := http.NewRequest("POST", ts.URL+"/posts/create", nil)
	req1.Header.Set("Authorization", "Bearer read_only_token")
	resp1, _ := http.DefaultClient.Do(req1)
	fmt.Printf("HTTP Status:        %d (Forbidden)\n", resp1.StatusCode)
	fmt.Printf("WWW-Authenticate:   %s\n", resp1.Header.Get("WWW-Authenticate"))
	resp1.Body.Close()

	// 2. Чтение списка пользователей с read-only токеном
	fmt.Println("\n=== 2. Попытка чтения с токеном read_only_token ===")
	req2, _ := http.NewRequest("GET", ts.URL+"/users", nil)
	req2.Header.Set("Authorization", "Bearer read_only_token")
	resp2, _ := http.DefaultClient.Do(req2)
	fmt.Printf("HTTP Status:        %d (OK)\n", resp2.StatusCode)
	resp2.Body.Close()

	// 3. Создание поста с токеном admin_token
	fmt.Println("\n=== 3. Попытка записи с токеном admin_token ===")
	req3, _ := http.NewRequest("POST", ts.URL+"/posts/create", nil)
	req3.Header.Set("Authorization", "Bearer admin_token")
	resp3, _ := http.DefaultClient.Do(req3)
	fmt.Printf("HTTP Status:        %d (Created)\n", resp3.StatusCode)
	resp3.Body.Close()
}

package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// NaiveJWTValidator — уязвимый парсер JWT, доверяющий заголовку alg
func NaiveJWTValidator(tokenString string, hmacSecret []byte, rsaPub *rsa.PublicKey) (map[string]interface{}, error) {
	parts := strings.Split(tokenString, ".")
	if len(parts) != 3 {
		return nil, errors.New("неверный формат JWT (ожидалось 3 части)")
	}

	headerJSON, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, err
	}

	var header map[string]interface{}
	if err := json.Unmarshal(headerJSON, &header); err != nil {
		return nil, err
	}

	alg, _ := header["alg"].(string)

	// УЯЗВИМОСТЬ 1: Принятие alg: none
	if strings.ToLower(alg) == "none" {
		// Наивный сервер верит заголовку и не проверяет подпись!
		payloadBytes, _ := base64.RawURLEncoding.DecodeString(parts[1])
		var claims map[string]interface{}
		_ = json.Unmarshal(payloadBytes, &claims)
		return claims, nil
	}

	// УЯЗВИМОСТЬ 2: Algorithm Confusion (подмена RS256 на HS256)
	if alg == "HS256" {
		// Сервер думает, что должен проверить HMAC, но если ему передали rsaPub как секрет:
		signedData := parts[0] + "." + parts[1]
		h := hmac.New(sha256.New, hmacSecret)
		h.Write([]byte(signedData))
		expectedSig := h.Sum(nil)

		clientSig, _ := base64.RawURLEncoding.DecodeString(parts[2])
		if !hmac.Equal(clientSig, expectedSig) {
			return nil, errors.New("неверная HMAC подпись")
		}

		payloadBytes, _ := base64.RawURLEncoding.DecodeString(parts[1])
		var claims map[string]interface{}
		_ = json.Unmarshal(payloadBytes, &claims)
		return claims, nil
	}

	return nil, fmt.Errorf("неподдерживаемый алгоритм: %s", alg)
}

// SecurePASETOValidator — строгий валидатор без уязвимостей
func SecurePASETOValidator(token string) error {
	if !strings.HasPrefix(token, "v4.public.") && !strings.HasPrefix(token, "v4.local.") {
		return errors.New("PASETO REJECT: Недопустимый префикс токена. Никаких гибких alg заголовков!")
	}
	return nil
}

func main() {
	rsaPriv, _ := rsa.GenerateKey(rand.Reader, 2048)
	rsaPubBytes, _ := x509.MarshalPKIXPublicKey(&rsaPriv.PublicKey)

	fmt.Println("=== 1. Атака JWT: alg: none ===")
	// Атакующий подделывает права администратора
	headerNone := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"none","typ":"JWT"}`))
	claimsHacker := base64.RawURLEncoding.EncodeToString([]byte(`{"sub":"attacker","role":"super_admin"}`))
	noneToken := headerNone + "." + claimsHacker + "." // пустая подпись

	// Наивный сервер валидирует токен
	claims, err := NaiveJWTValidator(noneToken, []byte("secret"), &rsaPriv.PublicKey)
	if err == nil {
		fmt.Printf("ВЗЛОМ УСПЕШЕН: Сервер принял токен с alg:none! Права: %v\n\n", claims["role"])
	}

	fmt.Println("=== 2. Атака JWT: Algorithm Confusion ===")
	// Атакующий берет публичный ключ RSA сервера и подписывает им токен через HMAC-SHA256
	headerHS256 := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"HS256","typ":"JWT"}`))
	signedContent := headerHS256 + "." + claimsHacker
	h := hmac.New(sha256.New, rsaPubBytes) // Секретом выступает открытый ключ!
	h.Write([]byte(signedContent))
	forgedSig := base64.RawURLEncoding.EncodeToString(h.Sum(nil))
	forgedJWT := signedContent + "." + forgedSig

	// Сервер ожидал RS256, но перепутал ключ из-за заголовка клиента
	claims2, err2 := NaiveJWTValidator(forgedJWT, rsaPubBytes, &rsaPriv.PublicKey)
	if err2 == nil {
		fmt.Printf("ВЗЛОМ УСПЕШЕН: Algorithm Confusion сработал! Субъект: %v, Роль: %v\n\n",
			claims2["sub"], claims2["role"])
	}

	fmt.Println("=== 3. Защита PASETO ===")
	// В PASETO невозможно подсунуть alg:none или подменить алгоритм
	errPaseto := SecurePASETOValidator(noneToken)
	fmt.Printf("Результат проверки вредоносного токена в PASETO:\n%v\n", errPaseto)
}

under_the_hood:
В библиотеке `golang-jwt/jwt` защита от Algorithm Confusion реализована через обязательную проверку типа метода подписи внутри колбэка `Keyfunc`:
```go
token, err := jwt.Parse(tokenStr, func(t *jwt.Token) (interface{}, error) {
    if _, ok := t.Method.(*jwt.SigningMethodRSA); !ok {
        return nil, fmt.Errorf("unexpected signing method: %v", t.Header["alg"])
    }
    return rsaPublicKey, nil
})
```
Если разработчик забудет эту проверку (а многие начинающие разработчики ее опускают), библиотека попытается использовать `rsaPublicKey` для проверки HMAC, открывая критическую дыру в безопасности.

